/// <reference types="vite/client" />

/**
 * Build-time navigation projection for the author shell (task 07.5, D29).
 * Generated by the `selfpage-site-nav` plugin in `apps/author/vite.config.ts`
 * from the same content model the public site uses.
 */
declare module 'virtual:selfpage-site-nav' {
  import type { ShellNav } from '@selfpage/site-shell';

  export const shellNav: ShellNav;
  /** Validated `PUBLIC_SITE_ORIGIN` (development default `http://localhost:4321`). */
  export const publicSiteOrigin: string;
  /** Absolute public Blog URL (`PUBLIC_SITE_ORIGIN` + `BASE_PATH` + `blog/`). */
  export const publicBlogUrl: string;
}

interface ImportMetaEnv {
  /** No author-app values are read at runtime any more; kept for Vite typing. */
  readonly VITE_PUBLIC_BLOG_URL?: string;
}

interface ImportMeta {
  readonly env: ImportMetaEnv;
}
